'use strict';
const $=id=>document.getElementById(id),money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(v),shortMoney=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v);
const dateString=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const uid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
const key='healthypockets-v1',categories=['Housing','Food & groceries','Transport','Bills','School','Other essentials'];
const initial=()=>({version:1,plan:null,goal:null,transactions:[],recurring:[],demo:false});
let state=initial(),storageError=false,undo=null,toastTimer;
try{const raw=localStorage.getItem(key);if(raw){const value=JSON.parse(raw);if(value.version===1&&Array.isArray(value.transactions)){state=value;state.transactions=state.transactions.filter(t=>['income','expense','saving'].includes(t.type)&&typeof t.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(t.date)&&Number.isFinite(t.amount)&&t.amount>0);}}}catch{storageError=true;}
state.recurring=Array.isArray(state.recurring)?state.recurring:[];
function persist(){try{localStorage.setItem(key,JSON.stringify(state));storageError=false;$('save-status').textContent='Saved on this browser';}catch{storageError=true;$('save-status').textContent='Browser storage unavailable — changes last only this session';}}
function toast(message,withUndo=false){clearTimeout(toastTimer);$('toast').querySelector('span').textContent=message;$('undo-button').hidden=!withUndo;$('toast').hidden=false;toastTimer=setTimeout(()=>{$('toast').hidden=true;undo=null;},8000);}
function syncInputs(){const p=state.plan||{pay:'',frequency:'hourly',hours:20,extra:'',rate:20,essentials:{}};for(const id of ['pay','frequency','hours','extra'])$(id).value=p[id];$('savings-rate').value=p.rate;$('rate-label').textContent=p.rate+'%';$('hours-wrap').hidden=p.frequency!=='hourly';$('hours').required=p.frequency==='hourly';categories.forEach((name,i)=>$('essential-'+i).value=p.essentials[name]||'');const g=state.goal;$('goal-name').value=g?.name||'';$('goal-amount').value=g?.amount||'';$('goal-start').value=g?.start||'';}
categories.forEach((name,i)=>{const div=document.createElement('div'),label=document.createElement('label'),input=document.createElement('input');label.htmlFor='essential-'+i;label.textContent=name+' ($)';Object.assign(input,{id:'essential-'+i,type:'number',min:'0',max:'10000000',step:'0.01',placeholder:'0'});div.append(label,input);$('essential-inputs').append(div);});
$('month').value=dateString().slice(0,7);$('tx-date').value=dateString();
function render(){const month=$('month').value||dateString().slice(0,7),tot=Pockets.totals(state.transactions,month),b=state.plan?Pockets.monthPlan(state.plan,state.recurring,month):null;$('earned').textContent=money(tot.income);$('spent').textContent=money(tot.expense);$('saved').textContent=money(tot.saving);$('available').textContent=money(tot.available);$('available').style.color=tot.available<0?'#ad5939':'';$('demo-banner').hidden=!state.demo;$('plan-empty').hidden=!!b;$('plan-result').hidden=!b;
if(b){$('monthly-income').textContent=shortMoney(b.income);$('needs-value').textContent=money(b.essentials);$('wants-value').textContent=money(b.flexible);$('saving-value').textContent=money(b.savings);$('weekly-budget').textContent=money(b.weekly);const total=b.essentials+b.flexible+b.savings,n=total?b.essentials/total*100:0,w=total?b.flexible/total*100:0;$('donut').style.background=total?`conic-gradient(var(--navy) 0 ${n}%,var(--sky) ${n}% ${n+w}%,var(--teal) ${n+w}% 100%)`:'#eaf0f7';$('plan-note').classList.toggle('warning',b.deficit>0||b.savings<b.target);$('plan-note').textContent=b.deficit>0?`Your essentials exceed your income by ${money(b.deficit)} per month. Reduce costs or add income before allocating savings or flexible spending.`:b.income===0?'Add income to start a plan. You can update these numbers any time.':b.savings<b.target?`Your expenses leave ${money(b.savings)} for savings, below your ${money(b.target)} target. Flexible spending is $0 until you make more room.`:`Set aside ${money(b.savings)} a month and keep ${money(b.flexible)} for flexible spending. ${b.essentials===0?'Add essentials like rent and groceries to make this plan realistic.':'Your essentials are covered in this plan.'}`;const spendLimit=b.essentials+b.flexible;$('budget-caption').textContent=`${money(tot.expense)} / ${money(spendLimit)}`;$('spending-progress').value=spendLimit>0?Math.min(100,tot.expense/spendLimit*100):tot.expense?100:0;$('spending-note').textContent=tot.expense>spendLimit?`${money(tot.expense-spendLimit)} over your monthly spending plan.`:`${money(spendLimit-tot.expense)} left in your monthly spending plan.`;}
renderTransactions(month);renderGoal(b);renderHistory(month);renderPlanner(month);if(b)renderOptions(month);
if(storageError)$('save-status').textContent='Browser storage unavailable — changes last only this session';}
function renderTransactions(month){const list=state.transactions.filter(t=>t.date.startsWith(month)).sort((a,b)=>b.date.localeCompare(a.date)||b.created-a.created);$('transactions').replaceChildren();$('activity-empty').hidden=!!list.length;for(const t of list){const tr=document.createElement('tr'),desc=document.createElement('td'),title=document.createElement('div'),sub=document.createElement('small'),date=document.createElement('td'),amt=document.createElement('td'),action=document.createElement('td'),del=document.createElement('button');title.className='tx-title';title.textContent=t.name;sub.textContent=t.type==='income'?'Income':t.type==='saving'?'Savings transfer':t.category;desc.append(title,sub);date.textContent=new Date(t.date+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'});amt.className='amount right'+(t.type==='income'||t.type==='saving'?' positive':'');amt.textContent=(t.type==='income'?'+':t.type==='expense'?'−':'')+money(t.amount);del.className='delete';del.textContent='×';del.setAttribute('aria-label',`Delete ${t.name}`);del.addEventListener('click',()=>{const removed=t;state.transactions=state.transactions.filter(x=>x.id!==t.id);persist();render();undo=()=>{state.transactions.push(removed);persist();render();};toast('Transaction removed.',true);});action.append(del);tr.append(desc,date,amt,action);$('transactions').append(tr);}}
function renderGoal(b){$('goal-progress').hidden=!state.goal;if(!state.goal)return;const g=Pockets.goalProgress(state.goal,state.transactions.filter(t=>t.date<=dateString()),b?.savings||0);$('goal-total').textContent=money(g.saved);$('goal-target').textContent='of '+money(state.goal.amount);$('goal-bar').value=g.percent;$('goal-message').textContent=g.months===0?'You reached your goal. That’s a habit worth celebrating!':g.months===null?`${money(g.remaining)} to go. Build a plan with monthly savings to see your timeline.`:`About ${g.months} month${g.months===1?'':'s'} to go if you save ${money(b.savings)} each month.`;}
function renderHistory(month){$('history-chart').replaceChildren();const [year,m]=month.split('-').map(Number);const months=Array.from({length:6},(_,i)=>{const d=new Date(year,m-6+i,1);return{date:d,tot:Pockets.totals(state.transactions,dateString(d).slice(0,7))};});const peak=Math.max(1,...months.flatMap(x=>[x.tot.income,x.tot.expense,x.tot.saving]));for(const x of months){const col=document.createElement('div'),bars=document.createElement('div'),label=document.createElement('span'),values=document.createElement('div');col.className='chart-month';bars.className='bars';const name=x.date.toLocaleDateString('en-US',{month:'short',year:'2-digit'});for(const [type,color]of[['income','navy'],['expense','sky'],['saving','teal']]){const bar=document.createElement('div');bar.className='bar '+color;bar.style.height=(x.tot[type]/peak*100)+'%';bar.title=`${name} ${type}: ${money(x.tot[type])}`;bar.setAttribute('aria-label',bar.title);bars.append(bar);}label.textContent=name;values.className='chart-values';values.textContent=`${shortMoney(x.tot.income)} / ${shortMoney(x.tot.expense)} / ${shortMoney(x.tot.saving)}`;col.append(bars,label,values);$('history-chart').append(col);}}
$('frequency').addEventListener('change',()=>{$('hours-wrap').hidden=$('frequency').value!=='hourly';$('hours').required=$('frequency').value==='hourly';});$('savings-rate').addEventListener('input',()=>{$('rate-label').textContent=$('savings-rate').value+'%';});
$('plan-form').addEventListener('submit',e=>{e.preventDefault();const essentials={};categories.forEach((name,i)=>essentials[name]=Number($('essential-'+i).value)||0);state.plan={pay:Number($('pay').value),frequency:$('frequency').value,hours:Number($('hours').value)||0,extra:Number($('extra').value)||0,rate:Number($('savings-rate').value),essentials};persist();render();toast('Your monthly plan is ready.');});
$('goal-form').addEventListener('submit',e=>{e.preventDefault();const name=$('goal-name').value.trim();if(!name){$('goal-name').setCustomValidity('Give your goal a name.');$('goal-name').reportValidity();return;}state.goal={name,amount:Number($('goal-amount').value),start:Number($('goal-start').value)||0};persist();render();toast('Savings goal saved.');});$('goal-name').addEventListener('input',()=>{$('goal-name').setCustomValidity('');});
let recording=null;
function openTransaction(){recording=null;$('tx-date').removeAttribute('min');$('tx-date').removeAttribute('max');$('transaction-form').reset();const current=dateString();$('tx-date').value=$('month').value===current.slice(0,7)?current:$('month').value+'-01';updateCategory();$('transaction-dialog').showModal();$('tx-name').focus();}
function updateCategory(){const expense=$('tx-type').value==='expense';$('tx-category').hidden=!expense;document.querySelector('label[for="tx-category"]').hidden=!expense;}
for(const id of ['add-button','add-small'])$(id).addEventListener('click',openTransaction);$('close-dialog').addEventListener('click',()=>$('transaction-dialog').close());$('tx-type').addEventListener('change',updateCategory);
$('transaction-form').addEventListener('submit',e=>{e.preventDefault();const name=$('tx-name').value.trim();if(!name){$('tx-name').setCustomValidity('Add a description.');$('tx-name').reportValidity();return;}const t={...(recording?{recurringId:recording.id,recurringMonth:recording.month}:{}),id:uid(),created:Date.now(),name,amount:Pockets.cents(Number($('tx-amount').value)),type:$('tx-type').value,date:$('tx-date').value,category:$('tx-category').value};state.transactions.push(t);$('month').value=t.date.slice(0,7);persist();render();$('transaction-dialog').close();toast('Transaction added.');});$('tx-name').addEventListener('input',()=>{$('tx-name').setCustomValidity('');});
$('month').addEventListener('change',()=>{if(!$('month').value)$('month').value=dateString().slice(0,7);render();});$('undo-button').addEventListener('click',()=>{if(undo){undo();undo=null;$('toast').hidden=true;}});
$('demo-button').addEventListener('click',()=>{if(state.transactions.length||state.goal||state.plan||state.recurring.length){toast('Your data is already here. Add income to build your plan.');$('pay').focus();return;}state={version:1,demo:true,plan:{pay:16,frequency:'hourly',hours:20,extra:300,rate:20,essentials:{Housing:500,'Food & groceries':200,Transport:70,Bills:50,School:30,'Other essentials':0}},goal:{name:'A little breathing room',amount:1500,start:250},transactions:[],recurring:[]};const month=dateString().slice(0,7);for(const [name,amount,type,category,day]of[['Campus job paycheck',640,'income','Income',1],['Family support',300,'income','Income',2],['Rent',500,'expense','Housing',3],['Grocery run',48.75,'expense','Food & groceries',4],['Coffee with friends',8.5,'expense','Fun & personal',5],['Emergency fund',125,'saving','Savings',6]])state.transactions.push({id:uid(),created:Date.now(),name,amount,type,category,date:month+'-'+String(Math.min(day,new Date().getDate())).padStart(2,'0')});$('month').value=month;syncInputs();persist();render();toast('Example loaded. These are sample numbers.');});
$('clear-demo').addEventListener('click',()=>{const old=state;state=initial();syncInputs();persist();render();undo=()=>{state=old;syncInputs();persist();render();};toast('Ready for your own numbers.',true);});
document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelectorAll('nav a').forEach(x=>x.classList.remove('active'));a.classList.add('active');}));

function renderOptions(month){
  $('plan-options').replaceChildren();
  for(const [name,rate,description] of [['Low',10,'More room for today'],['Moderate',20,'A balanced pace'],['Aggressive',30,'Build savings faster']]){
    const b=Pockets.monthPlan(state.plan,state.recurring,month,rate),selected=state.plan.rate===rate;
    const card=document.createElement('article');card.className='plan-option'+(selected?' selected':'');
    card.innerHTML=`<span class="eyebrow">${rate}% TARGET</span><h3>${name}</h3><p>${description}</p><strong>${money(b.savings)}<small> savings / month</small></strong><dl><dt>Flexible / month</dt><dd>${money(b.flexible)}</dd><dt>Flexible / week</dt><dd>${money(b.weekly)}</dd><dt>12 months at this pace</dt><dd>${money(b.savings*12)}</dd></dl><p class="micro">${b.deficit?'Essentials exceed income.':b.savings<b.target?'Target limited by your expenses.':b.scheduled>b.income*rate/100?'Your scheduled savings set a higher minimum.':'Essentials: '+money(b.essentials)}</p>`;
    const button=document.createElement('button');button.className=selected?'primary full':'secondary full';button.textContent=selected?'✓ Selected':'Choose '+name.toLowerCase();button.setAttribute('aria-pressed',String(selected));button.onclick=()=>{state.plan.rate=rate;$('savings-rate').value=rate;persist();render();toast(name+' savings plan selected.');};card.append(button);$('plan-options').append(card);
  }
  $('comparison-month').textContent='Comparing '+monthLabel(month)+'. The 12-month figure assumes this month repeats. See the long-term table for changing schedules.'+( [10,20,30].includes(state.plan.rate)?'':' Your previous custom '+state.plan.rate+'% target is retained until you choose an option.');
}
function monthLabel(month){return new Date(month+'-01T12:00:00').toLocaleDateString('en-US',{month:'short',year:'numeric'});}
let editingRecurring=null;
function initPlanner(){
 $('timeline-start').value=Pockets.addMonths(dateString().slice(0,7),-3);
 $('timeline-start').onchange=()=>{if(!$('timeline-start').value)$('timeline-start').value=dateString().slice(0,7);render();};$('timeline-length').onchange=()=>render();
 $('add-recurring').onclick=()=>openRecurring();$('close-recurring').onclick=()=>$('recurring-dialog').close();
 $('rec-end').oninput=()=>$('rec-end').setCustomValidity('');$('rec-start').oninput=()=>$('rec-end').setCustomValidity('');$('rec-name').oninput=()=>$('rec-name').setCustomValidity('');
 $('recurring-form').onsubmit=e=>{e.preventDefault();if(!$('rec-name').value.trim()){$('rec-name').setCustomValidity('Enter a name.');$('rec-name').reportValidity();return;}if($('rec-end').value&&$('rec-end').value<$('rec-start').value){$('rec-end').setCustomValidity('Last month must be on or after the first month.');$('rec-end').reportValidity();return;}const item={id:editingRecurring||uid(),name:$('rec-name').value.trim(),type:$('rec-type').value,amount:Pockets.cents(Number($('rec-amount').value)),start:$('rec-start').value,end:$('rec-end').value};state.recurring=state.recurring.filter(r=>r.id!==item.id);state.recurring.push(item);persist();render();$('recurring-dialog').close();toast('Monthly schedule saved.');};
}
function openRecurring(item){editingRecurring=item?.id||null;$('recurring-form').reset();$('rec-end').setCustomValidity('');$('rec-name').setCustomValidity('');$('recurring-title').textContent=item?'Edit recurring item':'Add recurring item';for(const k of ['name','type','amount','start','end'])$('rec-'+k).value=item?.[k]??(k==='start'?$('month').value:k==='type'?'expense':'');$('recurring-dialog').showModal();$('rec-name').focus();}
function renderPlanner(month){
 $('recurring-list').replaceChildren();
 if(!state.recurring.length){const p=document.createElement('p');p.className='empty';p.textContent='No repeating items yet. Add rent, a phone bill, or a monthly savings contribution.';$('recurring-list').append(p);}
 for(const r of state.recurring){const row=document.createElement('div');row.className='recurring-row';const text=document.createElement('div'),title=document.createElement('strong'),sub=document.createElement('small');title.textContent=r.name+' · '+money(r.amount)+'/month';sub.textContent=(r.type==='saving'?'Savings':'Fixed expense')+' · '+monthLabel(r.start)+' → '+(r.end?monthLabel(r.end):'Ongoing');text.append(title,sub);const actions=document.createElement('div');actions.className='recurring-actions';const edit=document.createElement('button');edit.className='text-button';edit.textContent='Edit';edit.setAttribute('aria-label','Edit '+r.name);edit.onclick=()=>openRecurring(r);const del=document.createElement('button');del.className='text-button';del.textContent='Remove';del.setAttribute('aria-label','Remove '+r.name);del.onclick=()=>{state.recurring=state.recurring.filter(x=>x.id!==r.id);persist();render();undo=()=>{state.recurring.push(r);persist();render();};toast('Schedule removed. Recorded transactions kept.',true);};actions.append(edit,del);
 if(Pockets.activeItems([r],month).length){const logged=state.transactions.some(t=>t.recurringId===r.id&&t.recurringMonth===month),record=document.createElement('button');record.className='secondary';record.textContent=logged?'✓ Recorded for '+monthLabel(month):'Record for '+monthLabel(month);record.disabled=logged;record.onclick=()=>{openTransaction();recording={id:r.id,month};$('tx-name').value=r.name;$('tx-amount').value=r.amount;$('tx-type').value=r.type;$('tx-category').value='Other';updateCategory();$('tx-date').min=month+'-01';$('tx-date').max=Pockets.addMonths(month,1)+'-01';$('tx-date').max=dateString(new Date(Number(month.slice(0,4)),Number(month.slice(5)),0));};actions.append(record);}
 row.append(text,actions);$('recurring-list').append(row);}
 const start=$('timeline-start').value,count=Number($('timeline-length').value),rates=[['Low',10],['Moderate',20],['Aggressive',30]],rows=Pockets.timeline(state.plan,state.recurring,start,count,state.transactions),end=rows.at(-1),shortfalls=rows.filter(r=>r.deficit>0).length;
 $('timeline-summary').textContent=`${money(end.cumulative)} planned savings across ${rows.length} months`+(shortfalls?` · ${shortfalls} month(s) with an essentials shortfall`:'')+(!state.plan?' · Add income to calculate affordable savings.':'');
 $('timeline-options').replaceChildren();
 const range=`${monthLabel(start)} – ${monthLabel(rows.at(-1).month)}`;
 for(const [name,rate] of rates){const scenario=Pockets.timeline(state.plan,state.recurring,start,count,state.transactions,rate),total=scenario.at(-1).cumulative,card=document.createElement('article'),label=document.createElement('span'),amount=document.createElement('strong'),detail=document.createElement('small');card.className='timeline-option'+(state.plan?.rate===rate?' selected':'');label.className='eyebrow';label.textContent=name+(state.plan?.rate===rate?' · SELECTED':'');amount.textContent=money(total);detail.textContent=`${range} · ${money(total/count)} average per month`;card.append(label,amount,detail);$('timeline-options').append(card);}
 $('timeline-rows').replaceChildren();for(const r of rows){const tr=document.createElement('tr');if(r.month===dateString().slice(0,7))tr.className='current-month';const values=[monthLabel(r.month)+(r.month<dateString().slice(0,7)?' · Past':r.month===dateString().slice(0,7)?' · Now':' · Future'),money(r.income),money(r.essentials),money(r.savings)+(r.savings<r.target?' (limited)':''),r.deficit?money(r.deficit)+' shortfall':money(r.flexible),money(r.cumulative),[r.actual.income,r.actual.expense,r.actual.saving].map(money).join(' / ')];for(const v of values){const td=document.createElement('td');td.textContent=v;tr.append(td);}if(r.deficit)tr.children[4].className='shortfall';$('timeline-rows').append(tr);}
}

initPlanner();syncInputs();render();
